const ILU = '<svg class="ilu" viewBox="0 0 34 28" shape-rendering="crispEdges" role="img" aria-label="Buku dengan tanda centang"><rect x="4" y="4" width="28" height="22" fill="#353535"/><rect x="2" y="2" width="28" height="22" fill="#cfcfcf"/><rect x="4" y="4" width="24" height="18" fill="#060606"/><rect x="15" y="4" width="2" height="18" fill="#cfcfcf"/><path fill="#626262" d="M6 7h7v1H6zM6 10h7v1H6zM6 13h7v1H6zM6 16h7v1H6zM19 7h7v1h-7zM19 9h7v1h-7z"/><path fill="#b2b2b2" d="M19 14h1v2h-1zM20 15h1v2h-1zM21 16h1v2h-1zM22 15h1v2h-1zM23 14h1v2h-1zM24 13h1v2h-1zM25 12h1v2h-1zM26 11h1v2h-1z"/></svg>';

function layout(o) {
  const url = SITUS + (o.path || '/');
  const robots = o.noindex ? 'noindex,nofollow' : 'index,follow,max-image-preview:large,max-snippet:-1,max-video-preview:-1';
  const img = o.img || OG;
  const ld = o.ld ? '<script type="application/ld+json">' + jsonAman(o.ld) + '</script>' : '';
  return '<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">'
    + '<title>' + esc(o.judul) + '</title>'
    + '<meta name="description" content="' + esc(o.desk) + '">'
    + '<meta name="robots" content="' + robots + '">'
    + '<meta name="theme-color" content="#060606"><meta name="color-scheme" content="dark">'
    + '<meta name="author" content="4ndra"><meta name="application-name" content="Kunci Jawaban">'
    + (o.noindex ? '' : '<link rel="canonical" href="' + esc(url) + '"><link rel="alternate" hreflang="id" href="' + esc(url) + '"><link rel="alternate" hreflang="x-default" href="' + esc(url) + '">')
    + (o.prev ? '<link rel="prev" href="' + esc(SITUS + o.prev) + '">' : '') + (o.next ? '<link rel="next" href="' + esc(SITUS + o.next) + '">' : '')
    + '<meta property="og:type" content="' + (o.tipe || 'website') + '"><meta property="og:site_name" content="Kunci Jawaban"><meta property="og:locale" content="id_ID">'
    + '<meta property="og:title" content="' + esc(o.judul) + '"><meta property="og:description" content="' + esc(o.desk) + '"><meta property="og:url" content="' + esc(url) + '">'
    + '<meta property="og:image" content="' + esc(img) + '"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Kunci Jawaban buku sekolah di s.4ndra.com">'
    + '<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="' + esc(o.judul) + '"><meta name="twitter:description" content="' + esc(o.desk) + '"><meta name="twitter:image" content="' + esc(img) + '">'
    + (o.diubah ? '<meta property="article:modified_time" content="' + esc(o.diubah) + '">' : '')
    + '<link rel="icon" href="/ikon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/ikon.png"><link rel="manifest" href="/manifest.webmanifest">'
    + '<link rel="sitemap" type="application/xml" title="Peta Situs" href="/sitemap.xml">'
    + '<link rel="preload" href="/Daydream.otf" as="font" type="font/otf" crossorigin><link rel="preload" href="/PressStart2P.ttf" as="font" type="font/ttf" crossorigin>'
    + '<style>' + CSS + '</style>' + ld + '</head><body class="' + (o.kelas || '') + '">'
    + '<header class="hd"><div class="k bar"><a class="logo dd" href="/">Kunci Jawaban</a><nav aria-label="Utama"><a href="/"' + (o.nav === 'beranda' ? ' aria-current="page"' : '') + '>Beranda</a><a href="/#kategori">Kategori</a><a href="/sitemap.xml">Peta Situs</a></nav></div></header>'
    + '<main>' + o.isi + '</main>'
    + '<footer class="ft"><div class="k fg"><nav aria-label="Kaki"><a href="/">Beranda</a><a href="/#kategori">Kategori</a><a href="/sitemap.xml">Peta Situs</a></nav><p class="lb">Dibuat oleh <a href="https://4ndra.com" rel="noopener">4ndra</a></p></div></footer>'
    + (o.skrip ? '<script>' + o.skrip + '</script>' : '') + '</body></html>';
}

const emph = (s) => s
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/__([^_]+)__/g, '<strong>$1</strong>')
  .replace(/\*([^*\s][^*]*?)\*/g, '<em>$1</em>')
  .replace(/(^|[\s(])_([^_\s][^_]*?)_(?=[\s).,;:!?]|$)/g, '$1<em>$2</em>')
  .replace(/~~([^~]+)~~/g, '<del>$1</del>');

function mdInline(s) {
  const k = [];
  const put = (h) => { k.push(h); return '\u0001' + (k.length - 1) + '\u0001'; };
  s = s.replace(/`([^`]+)`/g, (a, t) => put('<code>' + esc(t) + '</code>'));
  s = s.replace(/\$(?!\s)([^$\n]*?[^\s$])\$/g, (a, t) => put('<span class="m">' + esc(t) + '</span>'));
  s = esc(s);
  s = s.replace(/!\[([^\]]*)\]\((https?:\/\/[^\s)]+)\)/g, (a, t, u) => put('<img src="' + u + '" alt="' + t + '" loading="lazy">'));
  s = s.replace(/\[([^\]]+)\]\(((?:https?:\/\/|\/)[^\s)]+)\)/g, (a, t, u) => put('<a href="' + u + '" rel="noopener">' + emph(t) + '</a>'));
  s = emph(s);
  let n = 0;
  while (/\u0001\d+\u0001/.test(s) && n++ < 6) s = s.replace(/\u0001(\d+)\u0001/g, (a, i) => k[i]);
  return s;
}

const barisTabel = (l) => l.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim());
const pemisahTabel = (l) => /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)*\|?\s*$/.test(l) && l.includes('-');
const itemDaftar = /^(\s*)([-*+]|(\d+)[.)])\s+(.*)$/;
const hr = /^\s*([-*_])(\s*\1){2,}\s*$/;

function lst(it, p, ind) {
  const ord = it[p].ord;
  const awal = ord && it[p].num !== 1 ? ' start="' + it[p].num + '"' : '';
  let h = '<' + (ord ? 'ol' + awal : 'ul') + '>';
  while (p < it.length && it[p].ind >= ind) {
    if (it[p].ind > ind) {
      const r = lst(it, p, it[p].ind);
      h = h.endsWith('</li>') ? h.slice(0, -5) + r[0] + '</li>' : h + '<li>' + r[0] + '</li>';
      p = r[1];
      continue;
    }
    h += '<li>' + mdInline(it[p].txt).replace(/\n/g, '<br>') + '</li>';
    p++;
  }
  return [h + '</' + (ord ? 'ol' : 'ul') + '>', p];
}

function md(src) {
  const L = String(src).replace(/\r\n?/g, '\n').split('\n');
  const o = [];
  let i = 0;
  const mulai = (l, n) => /^```/.test(l) || /^#{1,6}\s/.test(l) || /^\s*>/.test(l) || itemDaftar.test(l) || hr.test(l) || /^\s*\$\$/.test(l) || (l.includes('|') && n < L.length && pemisahTabel(L[n]));
  while (i < L.length) {
    const l = L[i];
    if (!l.trim()) { i++; continue; }
    if (/^```/.test(l)) {
      const b = [];
      i++;
      while (i < L.length && !/^```/.test(L[i])) b.push(L[i++]);
      i++;
      o.push('<pre><code>' + esc(b.join('\n')) + '</code></pre>');
      continue;
    }
    if (/^\s*\$\$/.test(l)) {
      let t = l.trim();
      if (t.length > 3 && /\$\$$/.test(t)) i++;
      else {
        const b = [t];
        i++;
        while (i < L.length && !/\$\$\s*$/.test(L[i])) b.push(L[i++]);
        if (i < L.length) b.push(L[i]);
        i++;
        t = b.join('\n');
      }
      o.push('<div class="m" data-b="1">' + esc(t.replace(/^\$\$|\$\$$/g, '').trim()) + '</div>');
      continue;
    }
    const hd = l.match(/^(#{1,6})\s+(.*)$/);
    if (hd) {
      const n = Math.min(6, hd[1].length + 1);
      o.push('<h' + n + '>' + mdInline(hd[2].replace(/\s+#+\s*$/, '')) + '</h' + n + '>');
      i++;
      continue;
    }
    if (hr.test(l)) { o.push('<hr>'); i++; continue; }
    if (l.includes('|') && i + 1 < L.length && pemisahTabel(L[i + 1])) {
      const kep = barisTabel(l);
      i += 2;
      const isi = [];
      while (i < L.length && L[i].trim() && L[i].includes('|')) isi.push(barisTabel(L[i++]));
      o.push('<div class="tb"><table><thead><tr>' + kep.map((c) => '<th>' + mdInline(c) + '</th>').join('') + '</tr></thead><tbody>'
        + isi.map((r) => '<tr>' + kep.map((c, x) => '<td>' + mdInline(r[x] || '') + '</td>').join('') + '</tr>').join('') + '</tbody></table></div>');
      continue;
    }
    if (/^\s*>/.test(l)) {
      const b = [];
      while (i < L.length && /^\s*>/.test(L[i])) b.push(L[i++].replace(/^\s*>\s?/, ''));
      o.push('<blockquote>' + md(b.join('\n')) + '</blockquote>');
      continue;
    }
    if (itemDaftar.test(l)) {
      const it = [];
      while (i < L.length) {
        const m = L[i].match(itemDaftar);
        if (m) { it.push({ ind: m[1].length, ord: !!m[3], num: m[3] ? parseInt(m[3], 10) : 1, txt: m[4] }); i++; }
        else if (L[i].trim() && /^\s{2,}/.test(L[i]) && it.length) { it[it.length - 1].txt += '\n' + L[i].trim(); i++; }
        else break;
      }
      const base = Math.min(...it.map((x) => x.ind));
      let p = 0;
      while (p < it.length) {
        const r = lst(it, p, base);
        o.push(r[0]);
        p = r[1] > p ? r[1] : p + 1;
      }
      continue;
    }
    const b = [];
    while (i < L.length && L[i].trim() && (b.length === 0 || !mulai(L[i], i + 1))) b.push(L[i++]);
    o.push('<p>' + mdInline(b.join('\n')).replace(/\n/g, '<br>') + '</p>');
  }
  return o.join('');
}

function ringkas(t, n) {
  const s = String(t).replace(/```[\s\S]*?```/g, ' ').replace(/!\[[^\]]*\]\([^)]*\)/g, ' ').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/[#>*_`|~$\\]/g, ' ').replace(/-{2,}/g, ' ').replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n - 1).replace(/\s+\S*$/, '') + '...' : s;
}

async function sb(env, jalur, opsi = {}) {
  const r = await fetch(env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/' + jalur, {
    method: opsi.method || 'GET',
    headers: { apikey: env.SUPABASE_KEY, Authorization: 'Bearer ' + env.SUPABASE_KEY, 'Content-Type': 'application/json', Prefer: opsi.prefer || 'return=representation' },
    body: opsi.body === undefined ? undefined : JSON.stringify(opsi.body)
  });
  if (!r.ok) {
    const e = new Error(r.status === 409 ? 'Slug sudah dipakai' : 'Database gagal (' + r.status + ')');
    e.status = r.status;
    throw e;
  }
  const t = await r.text();
  return t ? JSON.parse(t) : null;
}

const KOLOM_MAPEL = 'id,kategori_id,slug,nama,buku,deskripsi,urutan,jumlah_halaman,hal_min,hal_maks,diperbarui';

function cari(o, re, d = 0) {
  if (!o || typeof o !== 'object' || d > 4) return null;
  for (const k of Object.keys(o)) if (re.test(k) && (typeof o[k] === 'string' || typeof o[k] === 'number')) return String(o[k]);
  for (const k of Object.keys(o)) { const v = cari(o[k], re, d + 1); if (v) return v; }
  return null;
}

async function rubisBuat(teks) {
  const r = await fetch('https://api.rubis.app/v2/scrap', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ content: teks }) });
  if (!r.ok) throw new Error('Rubis ' + r.status);
  const j = await r.json();
  const id = cari(j, /^(id|scrapid|scrap_id)$/i);
  if (!id) throw new Error('Rubis tanpa id');
  return { id, owner: cari(j, /owner/i) };
}

async function rubisBaca(id) {
  const r = await fetch('https://api.rubis.app/v2/scrap/' + encodeURIComponent(id) + '/raw', { cf: { cacheTtl: 3600, cacheEverything: true } });
  if (!r.ok) throw new Error('Rubis ' + r.status);
  return JSON.parse(await r.text());
}

async function ambilJawaban(env, m) {
  if (m.rubis_id) {
    try { return await rubisBaca(m.rubis_id); } catch (e) { if (!m.cadangan) return null; }
  }
  return m.cadangan || null;
}

function validasi(o) {
  const g = [], h = [], w = [];
  if (!o || typeof o !== 'object' || !Array.isArray(o.halaman)) return { galat: ['Objek harus punya array "halaman"'] };
  o.halaman.forEach((e, n) => {
    const t = 'halaman[' + n + ']';
    const d = Number(e && e.dari);
    const s = Number(e && (e.sampai === undefined ? e.dari : e.sampai));
    if (!Number.isInteger(d) || d < 1) g.push(t + ': "dari" harus bilangan bulat mulai dari 1');
    else if (!Number.isInteger(s) || s < d) g.push(t + ': "sampai" harus bilangan bulat dan tidak lebih kecil dari "dari"');
    else if (typeof e.isi !== 'string' || !e.isi.trim()) g.push(t + ' (' + lab(d, s) + '): "isi" kosong');
    else h.push({ dari: d, sampai: s, judul: typeof e.judul === 'string' ? e.judul.trim().slice(0, 160) : '', isi: e.isi.trim() });
  });
  h.sort((a, b) => a.dari - b.dari || a.sampai - b.sampai);
  const ada = new Set();
  h.forEach((e, n) => {
    const k = e.dari + '-' + e.sampai;
    if (ada.has(k)) g.push('Halaman ' + lab(e.dari, e.sampai) + ' muncul lebih dari sekali');
    ada.add(k);
    if (n && e.dari <= h[n - 1].sampai) w.push('Halaman ' + lab(e.dari, e.sampai) + ' tumpang tindih dengan ' + lab(h[n - 1].dari, h[n - 1].sampai));
  });
  if (!h.length && !g.length) g.push('Tidak ada halaman');
  const buku = typeof o.buku === 'string' ? o.buku.trim().slice(0, 200) : '';
  const hasil = { buku, halaman: h };
  if (JSON.stringify(hasil).length > 2900000) g.push('Ukuran JSON melebihi 2,9 MB, pecah menjadi beberapa mata pelajaran');
  return { hasil, galat: g.slice(0, 20), peringatan: w.slice(0, 20) };
}

function celah(h) {
  if (!h.length) return [];
  const maks = Math.max(...h.map((e) => e.sampai));
  if (maks > 5000) return [];
  const t = new Uint8Array(maks + 2);
  h.forEach((e) => { for (let x = e.dari; x <= e.sampai; x++) t[x] = 1; });
  const o = [];
  let a = 0;
  for (let x = h[0].dari; x <= maks; x++) {
    if (!t[x] && !a) a = x;
    if (t[x] && a) { o.push(lab(a, x - 1)); a = 0; }
  }
  return o.slice(0, 40);
}

function ringkasan(v) {
  const h = v.hasil ? v.hasil.halaman : [];
  return { jumlah: h.length, hal_min: h.length ? h[0].dari : null, hal_maks: h.length ? Math.max(...h.map((e) => e.sampai)) : null, galat: v.galat || [], peringatan: v.peringatan || [], celah: celah(h) };
}

async function samaAman(a, b) {
  const e = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest('SHA-256', e.encode(a)), crypto.subtle.digest('SHA-256', e.encode(b))]);
  const p = new Uint8Array(x), q = new Uint8Array(y);
  let d = 0;
  for (let i = 0; i < p.length; i++) d |= p[i] ^ q[i];
  return d === 0;
}

const json = (o, s = 200) => new Response(JSON.stringify(o), { status: s, headers: { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Robots-Tag': 'noindex' } });

function bersih(t, maks) { return String(t ?? '').trim().slice(0, maks); }

async function admin(req, env, url, p) {
  if (!env.KEY || !(await samaAman(req.headers.get('x-key') || '', env.KEY))) return json({ galat: 'Kunci salah' }, 401);
  const rute = p.slice('/admin/api/'.length);
  try {
    if (rute === 'data' && req.method === 'GET') {
      const [k, m] = await Promise.all([
        sb(env, 'kategori?select=*&order=urutan.asc,nama.asc'),
        sb(env, 'mapel?select=' + KOLOM_MAPEL + ',rubis_id&order=urutan.asc,nama.asc')
      ]);
      return json({ kategori: k, mapel: m.map((x) => ({ ...x, rubis: !!x.rubis_id, rubis_id: undefined })) });
    }
    if (rute === 'kategori' && req.method === 'POST') {
      const b = await req.json();
      const rec = { nama: bersih(b.nama, 120), slug: bersih(b.slug, 80), deskripsi: bersih(b.deskripsi, 600), urutan: parseInt(b.urutan, 10) || 0 };
      if (!rec.nama) return json({ galat: 'Nama wajib diisi' }, 400);
      if (!SLUG.test(rec.slug) || RESERVED.has(rec.slug)) return json({ galat: 'Slug tidak valid atau dilarang' }, 400);
      if (b.id) {
        if (!UUID.test(b.id)) return json({ galat: 'ID tidak valid' }, 400);
        await sb(env, 'kategori?id=eq.' + b.id, { method: 'PATCH', body: rec });
      } else await sb(env, 'kategori', { method: 'POST', body: rec });
      return json({ ok: true });
    }
    if (rute === 'kategori' && req.method === 'DELETE') {
      const id = url.searchParams.get('id') || '';
      if (!UUID.test(id)) return json({ galat: 'ID tidak valid' }, 400);
      await sb(env, 'kategori?id=eq.' + id, { method: 'DELETE', prefer: 'return=minimal' });
      return json({ ok: true });
    }
    if (rute === 'mapel' && req.method === 'POST') {
      const b = await req.json();
      const rec = { nama: bersih(b.nama, 120), slug: bersih(b.slug, 80), buku: bersih(b.buku, 200), deskripsi: bersih(b.deskripsi, 600), urutan: parseInt(b.urutan, 10) || 0 };
      if (!rec.nama) return json({ galat: 'Nama wajib diisi' }, 400);
      if (!SLUG.test(rec.slug)) return json({ galat: 'Slug tidak valid' }, 400);
      if (b.id) {
        if (!UUID.test(b.id)) return json({ galat: 'ID tidak valid' }, 400);
        await sb(env, 'mapel?id=eq.' + b.id, { method: 'PATCH', body: rec });
      } else {
        if (!UUID.test(b.kategori_id || '')) return json({ galat: 'Kategori tidak valid' }, 400);
        await sb(env, 'mapel', { method: 'POST', body: { ...rec, kategori_id: b.kategori_id } });
      }
      return json({ ok: true });
    }
    if (rute === 'mapel' && req.method === 'DELETE') {
      const id = url.searchParams.get('id') || '';
      if (!UUID.test(id)) return json({ galat: 'ID tidak valid' }, 400);
      await sb(env, 'mapel?id=eq.' + id, { method: 'DELETE', prefer: 'return=minimal' });
      return json({ ok: true });
    }
    if (rute === 'jawaban' && req.method === 'GET') {
      const id = url.searchParams.get('id') || '';
      if (!UUID.test(id)) return json({ galat: 'ID tidak valid' }, 400);
      const a = await sb(env, 'mapel?select=rubis_id,cadangan&id=eq.' + id + '&limit=1');
      if (!a || !a[0]) return json({ galat: 'Tidak ditemukan' }, 404);
      const j = await ambilJawaban(env, a[0]);
      return json({ data: j });
    }
    if (rute === 'jawaban' && req.method === 'POST') {
      const b = await req.json();
      if (!UUID.test(b.mapel_id || '')) return json({ galat: 'Mata pelajaran tidak valid' }, 400);
      let o;
      try { o = JSON.parse(String(b.json || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '')); } catch (e) { return json({ galat: 'JSON tidak valid: ' + e.message }, 400); }
      let v = validasi(o);
      if (b.gabung && v.hasil && !v.galat.length) {
        const a = await sb(env, 'mapel?select=rubis_id,cadangan&id=eq.' + b.mapel_id + '&limit=1');
        const lama = a && a[0] ? await ambilJawaban(env, a[0]) : null;
        if (lama && Array.isArray(lama.halaman)) {
          const peta = new Map(lama.halaman.map((e) => [e.dari + '-' + e.sampai, e]));
          v.hasil.halaman.forEach((e) => peta.set(e.dari + '-' + e.sampai, e));
          v = validasi({ buku: v.hasil.buku || lama.buku, halaman: [...peta.values()] });
        }
      }
      const rs = ringkasan(v);
      if (v.galat.length || b.uji) return json({ ...rs, tersimpan: false }, v.galat.length ? 400 : 200);
      const teks = JSON.stringify(v.hasil);
      let sumber = 'rubis', rid = null, rown = null, cad = null;
      try { const r = await rubisBuat(teks); rid = r.id; rown = r.owner; } catch (e) { sumber = 'cadangan'; cad = v.hasil; }
      const daftar = v.hasil.halaman.map((e) => [e.dari, e.sampai, e.judul]);
      await sb(env, 'mapel?id=eq.' + b.mapel_id, { method: 'PATCH', body: { rubis_id: rid, rubis_owner: rown, cadangan: cad, daftar_halaman: daftar, jumlah_halaman: rs.jumlah, hal_min: rs.hal_min, hal_maks: rs.hal_maks, buku: v.hasil.buku || undefined } });
      return json({ ...rs, tersimpan: true, sumber });
    }
    return json({ galat: 'Tidak ditemukan' }, 404);
  } catch (e) {
    return json({ galat: e.message || 'Gagal' }, e.status === 409 ? 409 : 500);
  }
}

